    if ((estimated == NULL) || (target == NULL) || (error == NULL)) {
        return ADCS_E_NULL;
    }

    // Check for non-finite inputs
    if ((!isfinite(estimated->w)) || (!isfinite(estimated->x)) || 
        (!isfinite(estimated->y)) || (!isfinite(estimated->z)) ||
        (!isfinite(target->w)) || (!isfinite(target->x)) || 
        (!isfinite(target->y)) || (!isfinite(target->z))) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    adcs_quat_t est_norm, tgt_norm;
    if (adcs_quat_normalize(estimated, &est_norm) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_quat_normalize(target, &tgt_norm) != ADCS_OK) {
        error->x = 0.0;
        error->y = 0.0;
        error->z = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t q_err = adcs_quat_multiply(&tgt_norm, &adcs_quat_conjugate(&est_norm));

    // Choose shortest representative
    if (q_err.w < 0.0) {
        q_err.w = -q_err.w;
        q_err.x = -q_err.x;
        q_err.y = -q_err.y;
        q_err.z = -q_err.z;
    }

    double s = sqrt(q_err.x * q_err.x + q_err.y * q_err.y + q_err.z * q_err.z);

    if (s <= 1e-12) {
        error->x = 2.0 * q_err.x;
        error->y = 2.0 * q_err.y;
        error->z = 2.0 * q_err.z;
    } else {
        double angle = 2.0 * atan2(s, q_err.w);
        double scale = angle / s;
        error->x = scale * q_err.x;
        error->y = scale * q_err.y;
        error->z = scale * q_err.z;
    }

    return ADCS_OK;
}

